mapper.select:
select * from question where 1=1
and title like concat('%', #{req.title}, '%')
and status = #{req.status}
and question_type = #{req.questionType}
order by updated_at desc

SELECT CONCAT(YEAR(created_at), '-W', LPAD(WEEK(created_at, 3), 2, '0')) as `time`,
COUNT(*) as `count`
FROM question


        and product_module = concat('%', #{req.productModule}, '%')



        and created_at >= #{req.startDate}



        and created_at <= #{req.endDate}


GROUP BY `time`
ORDER BY `time`;

SELECT CONCAT(YEAR(created_at), '-', LPAD(MONTH(created_at), 2, '0')) as `time`,
COUNT(*) as `count`
FROM question


        and product_module = concat('%', #{req.productModule}, '%')



        and created_at >= #{req.startDate}



        and created_at <= #{req.endDate}


GROUP BY `time`
ORDER BY `time`;
